/**
 * Generated API types for the backend's `/v1` OpenAPI surface.
 *
 * `schema.ts` is generated by `pnpm gen` (openapi-typescript) from adh's `/v1`
 * spec, `openapi.v1.json` — committed in the adhbackend repo at
 * `src/adh/openapi.v1.json` and served live at
 * https://api.agenticdeveloperhub.com/v1/openapi.json. It is NOT in this repo, so
 * the spec is an explicit input (a path or URL as the first argument, or
 * `ADH_OPENAPI_SPEC`), never derived. Do not edit `schema.ts` by hand; regenerate
 * after any backend route/schema change. The committed file is what ships, so a
 * consumer without an adh checkout builds fine.
 *
 * `/v1` is Stripe-shaped: snake_case fields, `created`/`updated` as unix seconds,
 * collections as `{object: 'list', data, has_more, url}`, update as POST on the
 * item path, DELETE answering a `{id, object, deleted}` tombstone.
 */
export type { paths, components } from './schema'

import type { paths } from './schema'

/** Unwrap the `application/json` body out of an OpenAPI response object. */
type JsonBody<T> = T extends { content: { 'application/json': infer B } } ? B : never

/**
 * The JSON body of a successful response for an operation, keyed by path +
 * method (status defaults to 200). Examples:
 *   SuccessBody<'/v1/customers', 'get'>                // the 200 list envelope
 *   SuccessBody<'/v1/customers', 'get'>['data'][number] // one listed row
 *   SuccessBody<'/v1/customers', 'post', 201>          // the 201 create body
 *
 * A backend schema change regenerates `schema.ts`, so any consumer reading a
 * removed/renamed field stops type-checking — that's the contract guard.
 */
export type SuccessBody<
  P extends keyof paths,
  M extends keyof paths[P],
  Status extends number = 200,
> = paths[P][M] extends { responses: Record<Status, infer R> } ? JsonBody<R> : never

/**
 * The JSON request body for an operation, keyed by path + method. Examples:
 *   RequestBody<'/v1/customers', 'post'>        // the create payload
 *   RequestBody<'/v1/customers/{id}', 'post'>   // an update (every field optional)
 *
 * Server-managed columns (id, `created`/`updated`, sync bookkeeping) are already
 * stripped from the generated create schema. Typing an outgoing payload with
 * this means a backend change to the WRITABLE columns (rename, new required
 * field) stops the `JSON.stringify(body)` call from type-checking — the write
 * side of the contract guard.
 */
export type RequestBody<P extends keyof paths, M extends keyof paths[P]> =
  paths[P][M] extends { requestBody?: infer R } ? JsonBody<NonNullable<R>> : never
